css:
:root{--radius:3px!important;--radius-sm:1px!important;--radius-md:2px!important;--radius-lg:3px!important;--radius-xl:4px!important}
::selection{background:#5eead4;color:#04201c}
*{caret-color:#5eead4}
[data-message-role="assistant"]{border-left:1px dashed #2e323a;padding-left:12px}
.chat-markdown h1,.chat-markdown h2,.chat-markdown h3{font-family:ui-monospace,Menlo,monospace;text-transform:uppercase;letter-spacing:.06em;color:#5eead4}
.chat-markdown h1::before,.chat-markdown h2::before,.chat-markdown h3::before{content:"// ";color:#5b606b}
[data-workspace-area="conversation"]::after{content:"";position:fixed;inset:0;pointer-events:none;background:repeating-linear-gradient(0deg,rgba(255,255,255,.012) 0 1px,transparent 1px 3px)}
[data-slot="switch"][data-checked],[data-slot="switch"][aria-checked="true"]{box-shadow:0 0 12px #5eead455}

:root{--tl-a:#5eead4;--tl-l:#22242a;--tl-l2:#2e323a}
body,[data-chat-header],[data-thread-item],[data-thread-details-card],.composer-tiptap,[data-slot="button"],[data-slot="input"]{font-family:ui-monospace,"SF Mono",SFMono-Regular,Menlo,monospace!important}
.chat-markdown{font-family:ui-sans-serif,system-ui,sans-serif}
[data-workspace-area="conversation"]{background-color:#0a0a0c!important;background-image:radial-gradient(circle,#262a32 1px,transparent 1.6px)!important;background-size:22px 22px!important}
[data-chat-header]{border-bottom:1px solid var(--tl-l)!important;letter-spacing:.04em;text-transform:uppercase;font-size:12px}
[data-slot="sidebar"]{border-right:1px solid var(--tl-l)!important}
[data-thread-item] [data-sidebar-row]{border-left:2px solid transparent!important;border-radius:2px!important}
[data-thread-item] [data-sidebar-row]:hover{border-left-color:var(--tl-l2)!important}
[data-thread-item] [aria-current]:not([aria-current="false"]){border-left-color:var(--tl-a)!important}
[data-slot="composer-host"],[data-thread-details-card],[data-slot="dialog-popup"],[data-slot="popover-popup"],[data-slot="menu-popup"]{border:1px solid var(--tl-l2)!important;border-radius:3px!important;box-shadow:none!important;
 background-image:linear-gradient(var(--tl-a),var(--tl-a)),linear-gradient(var(--tl-a),var(--tl-a)),linear-gradient(var(--tl-a),var(--tl-a)),linear-gradient(var(--tl-a),var(--tl-a))!important;
 background-size:10px 1px,1px 10px,10px 1px,1px 10px!important;background-position:0 0,0 0,100% 100%,100% 100%!important;background-repeat:no-repeat!important}
[data-slot="composer-host"]:focus-within{border-color:var(--tl-a)!important;box-shadow:0 0 0 1px #5eead433,0 0 24px #5eead414!important}
[data-user-message-bubble]{border:1px solid var(--tl-l2)!important;border-left:2px solid var(--tl-a)!important;border-radius:2px!important}
.chat-markdown-codeblock{border:1px solid var(--tl-l)!important;border-radius:2px!important}
[data-slot="button"],[data-slot="input"],[data-slot="select-trigger"]{border-radius:2px!important}
[data-slot="tooltip-popup"]{border:1px solid var(--tl-a)!important;border-radius:2px!important;font-family:ui-monospace,"SF Mono",SFMono-Regular,Menlo,monospace!important}
svg.lucide{stroke-width:1.6}
::-webkit-scrollbar{width:8px;height:8px}::-webkit-scrollbar-thumb{background:#2e323a;border-radius:0}::-webkit-scrollbar-thumb:hover{background:#5eead4}
